#include <stdio.h>
int main(void) {
    int a, b;
    scanf("%d%d", &a, &b);
    printf("Sum = %d\n", a + b);
    printf("Difference = %d\n", a - b);
    printf("Product = %d\n", a * b);
    if (b != 0) {
        printf("Quotient = %d\n", a / b);
        printf("Remainder = %d\n", a % b);
    } else {
        printf("Division by zero is not allowed.\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int a, b, c, greatest;
    scanf("%d%d%d", &a, &b, &c);
    if (a >= b && a >= c) greatest = a;
    else if (b >= a && b >= c) greatest = b;
    else greatest = c;
    printf("Greatest = %d\n", greatest);
    return 0;
}

#include <stdio.h>
int main(void) {
    double a, b; char op;
    scanf("%lf %c %lf", &a, &op, &b);
    switch (op) {
        case '+': printf("%.2f\n", a + b); break;
        case '-': printf("%.2f\n", a - b); break;
        case '*': printf("%.2f\n", a * b); break;
        case '/': if (b != 0) printf("%.2f\n", a / b); else printf("Division by zero\n"); break;
        default: printf("Invalid operator\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int n, i; unsigned long long fact = 1;
    scanf("%d", &n);
    if (n < 0) printf("Factorial is undefined.\n");
    else {
        for (i = 2; i <= n; i++) fact *= i;
        printf("%llu\n", fact);
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int n, i, prime = 1;
    scanf("%d", &n);
    if (n < 2) prime = 0;
    for (i = 2; i * i <= n && prime; i++) {
        if (n % i == 0) prime = 0;
    }
    printf(prime ? "Prime\n" : "Not prime\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int n, original, digit, reversed = 0;
    scanf("%d", &n);
    original = n;
    while (n > 0) {
        digit = n % 10;
        reversed = reversed * 10 + digit;
        n /= 10;
    }
    printf("Reverse = %d\n", reversed);
    printf(original == reversed ? "Palindrome\n" : "Not palindrome\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int n, row, col, space;
    scanf("%d", &n);
    for (row = 0; row < n; row++) {
        unsigned long long value = 1;
        for (space = 0; space < n - row - 1; space++) printf(" ");
        for (col = 0; col <= row; col++) {
            printf("%llu ", value);
            value = value * (row - col) / (col + 1);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
int gcd(int a, int b) {
    while (b != 0) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}
int main(void) {
    int a, b;
    scanf("%d%d", &a, &b);
    printf("GCD = %d\n", gcd(a, b));
    return 0;
}

#include <stdio.h>
unsigned long long factorial(unsigned int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}
int main(void) {
    unsigned int n;
    scanf("%u", &n);
    printf("%llu\n", factorial(n));
    return 0;
}

#include <stdio.h>
int digitSum(unsigned int n) {
    if (n < 10) return (int)n;
    return (int)(n % 10) + digitSum(n / 10);
}
int main(void) {
    unsigned int n;
    scanf("%u", &n);
    printf("Sum = %d\n", digitSum(n));
    return 0;
}
